#include <vector>
#define main hecbench_original_main
#include "f16max-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):4096,repeat=argc>2?atoi(argv[2]):10;std::vector<half>a(2*n),b(2*n),out(2*n);std::vector<double>expected;for(int i=0;i<2*n;i++){a[i]=__float2half(float((i*17)%257-128)+.125f);b[i]=__float2half(float((i*31)%251-125)+.375f);expected.push_back(fmaxf(__half2float(a[i]),__half2float(b[i])));}std::vector<double>copy=expected;expected.insert(expected.end(),copy.begin(),copy.end());half *da,*db,*dr;cudaMalloc(&da,4*n);cudaMalloc(&db,4*n);cudaMalloc(&dr,4*n);cudaMemcpy(da,a.data(),4*n,cudaMemcpyHostToDevice);cudaMemcpy(db,b.data(),4*n,cudaMemcpyHostToDevice);auto launch=[&](int c){if(c==1)hmax<half2><<<(n+255)/256,256>>>((half2*)da,(half2*)db,(half2*)dr,n);else hmax<half><<<(2*n+255)/256,256>>>(da,db,dr,2*n);};launch(1);launch(2);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){std::vector<double>values;double total=0;for(int c=1;c<=2;c++){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)launch(c);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;cudaMemcpy(out.data(),dr,4*n,cudaMemcpyDeviceToHost);for(auto v:out)values.push_back(__half2float(v));}emit(trial,total,values,expected,repeat);}cudaFree(da);cudaFree(db);cudaFree(dr);return 0;}
